'use strict';

// MAIN //

/**
* Returns a new change event object.
*
* @private
* @param {string} property - property name
* @returns {Object} event object
*/
function event( property ) { // eslint-disable-line stdlib/no-redeclare
	return {
		'type': 'update',
		'source': 'from', // TODO: should this be `from`, which is the property name to which this should be assigned, or `data-source`, the originating object?
		'property': property
	};
}


// EXPORTS //

module.exports = event;
